mapper.select:
SELECT f.id, f.eir_id, f.plate_no, f.company_id, f.amount, f.pay_status, f.pay_time, f.operator, f.create_time, c.name AS companyName, e.eir_no AS eirNo, e.business_type AS businessType FROM fee_record f LEFT JOIN transport_company c ON c.id = f.company_id LEFT JOIN eir_order e ON e.id = f.eir_id
AND e.eir_no LIKE CONCAT('%', #{eirNo}, '%')
AND f.company_id = #{companyId}
AND f.pay_status = #{payStatus}
ORDER BY f.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM fee_record f


        AND f.eir_id IN (SELECT id FROM eir_order WHERE eir_no LIKE CONCAT('%', #{eirNo}, '%'))


        AND f.company_id = #{companyId}


        AND f.pay_status = #{payStatus}

mapper.update:
UPDATE fee_record
SET pay_status = 1, pay_time = NOW(), operator = #{operator}
WHERE id = #{id} AND pay_status = 0

