mapper.select:
SELECT f.company_id AS companyId, c.code AS companyCode, c.name AS companyName, COUNT(1) AS totalCount, SUM(CASE WHEN f.pay_status = 1 THEN 1 ELSE 0 END) AS paidCount, SUM(CASE WHEN f.pay_status = 0 THEN 1 ELSE 0 END) AS unpaidCount, IFNULL(SUM(CASE WHEN f.pay_status = 1 THEN f.amount ELSE 0 END), 0) AS paidAmount, SUM(f.amount) AS totalAmount FROM fee_record f LEFT JOIN transport_company c ON c.id = f.company_id
f.company_id = #{companyId}
GROUP BY f.company_id, c.code, c.name ORDER BY f.company_id ASC
